mapper.select:
SELECT
    
FROM
    TBL_TKT_ES_INFO

    
        AND ES_CODE = #{esCode}
    
    
        AND ES_NAME = #{esName}
    
    
        AND INST_NO = #{instNo}
    
    
        AND MAKE_NUM = #{makeNum}
    
    
        AND WASH_NUM = #{washNum}
    
    
        AND WALE_NUM = #{waleNum}
    
    
        AND CANCEL_NUM = #{cancelNum}
    
    
        AND WORK_TIMES = #{workTimes}
    
    
        AND ES_STAT = #{esStat}
    
    
        AND LOGIN_STAT = #{loginStat}
    
    
        AND LOGIN_USER = #{loginUser}
    
    
        AND LAST_UPD_ID = #{lastUpdId}
    
    
        AND LAST_UPD_TMS = #{lastUpdTms}
    

ORDER BY ES_CODE
